    input  wire reset,
    output wire shift_ena
);

    // We need to count 4 cycles: 0, 1, 2, 3. A 2-bit counter is sufficient.
    reg [1:0] count;
    reg       active;

    always @(posedge clk) begin
        if (reset) begin
            count  <= 2'b00;
            active <= 1'b1;     // Start active upon reset
        end else begin
            if (active) begin
                if (count == 2'b11) begin
                    active <= 1'b0; // Stop after 4 cycles
                end else begin
                    count <= count + 2'b01;
                end
            end
        end
    end

    // Assert shift_ena for the first 4 cycles, then 0 forever.
    assign shift_ena = active;

endmodule
